label.text:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	span = ifElse($period == 0,
		#('All'@en, 'Alle'@de).localize(),
		ifElse($period == 1,
			#('1 day'@en, '1 Tag'@de).localize(),
			#('{0} days'@en, '{0} Tage'@de).fill($period).localize()));
	#('Runs ({0})'@en, 'Läufe ({0})'@de).fill($span).localize();
}

description.text:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	executions = all(`tl.ai.execution:AgentExecution`);
	recent = ifElse($period == 0, $executions,
		$executions.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`)
			>= now().toSystemCalendar().withDayAdded(-$period).toDate()));
	children = $recent.filter(e -> !isEmpty($e.get(`tl.ai.execution:AgentExecution#parentExecution`))).size();
	{{{
		<div class="aiKpi">
			<div class="aiKpiValue">{numberFormat('#,##0').format($recent.size())}</div>
			<div class="aiKpiNote">
				{#('{0} of them sub-agents'@en, 'davon {0} Teilagenten'@de).fill($children)}
			</div>
		</div>
	}}};
}

modelBuilder.elements:
model -> {
	period = ifElse(isEmpty($model), 30, $model);
	executions = all(`tl.ai.execution:AgentExecution`);
	ifElse($period == 0, $executions,
		$executions.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`)
			>= now().toSystemCalendar().withDayAdded(-$period).toDate()));
}
